56	    and 255 << PRECISION_BITS (16320) is highest value.
57	*/
58	Imaging
59	ImagingColorLUT3D_linear(
60	    Imaging imOut,
61	    Imaging imIn,
62	    int table_channels,
63	    int size1D,
64	    int size2D,
65	    int size3D,
66	    INT16 *table) {
67	    /* This float to int conversion doesn't have rounding
68	       error compensation (+0.5) for two reasons:
69	       1. As we don't hit the highest value,
70	          we can use one extra bit for precision.
71	       2. For every pixel, we interpolate 8 elements from the table:
72	          current and +1 for every dimension and their combinations.
73	          If we hit the upper cells from the table,
74	          +1 cells will be outside of the table.
75	          With this compensation we never hit the upper cells
76	          but this also doesn't introduce any noticeable difference. */
