78	    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
79	    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
80	    int size1D_2D = size1D * size2D;
81	    int x, y;
82	    ImagingSectionCookie cookie;
83	
84	    if (table_channels < 3 || table_channels > 4) {
85	        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
86	        return NULL;
87	    }
88	
89	    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
90	        imIn->bands < 3 || imOut->bands < table_channels) {
91	        return (Imaging)ImagingError_ModeError();
92	    }
93	
94	    /* In case we have one extra band in imOut and don't have in imIn.*/
95	    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
96	        return (Imaging)ImagingError_ModeError();
97	    }
98	
99	    ImagingSectionEnter(&cookie);
100	    for (y = 0; y < imOut->ysize; y++) {
101	        UINT8 *rowIn = (UINT8 *)imIn->image[y];
102	        char *rowOut = (char *)imOut->image[y];
103	        for (x = 0; x < imOut->xsize; x++) {
104	            UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
105	            UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
106	            UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
107	            INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
108	            INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
109	            INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
