123	                    leftright,
124	                    &table[idx + size1D * 3],
125	                    &table[idx + size1D * 3 + 3],
126	                    shift1D);
127	                interpolate3(left, leftleft, leftright, shift2D);
128	
129	                interpolate3(
130	                    rightleft,
131	                    &table[idx + size1D_2D * 3],
132	                    &table[idx + size1D_2D * 3 + 3],
133	                    shift1D);
