751	static INT16 *
752	_prepare_lut_table(PyObject *table, Py_ssize_t table_size) {
753	    int i;
754	    Py_buffer buffer_info;
755	    INT32 data_type = TYPE_FLOAT32;
756	    float item = 0;
757	    void *table_data = NULL;
758	    int free_table_data = 0;
759	    INT16 *prepared;
760	
761	/* NOTE: This value should be the same as in ColorLUT.c */
762	#define PRECISION_BITS (16 - 8 - 2)
763	
764	    const char *wrong_size =
765	        ("The table should have table_channels * "
766	         "size1D * size2D * size3D float items.");
767	
768	    if (PyObject_CheckBuffer(table)) {
769	        if (!PyObject_GetBuffer(table, &buffer_info, PyBUF_CONTIG_RO | PyBUF_FORMAT)) {
770	            if (buffer_info.ndim == 1 && buffer_info.shape[0] == table_size) {
771	                if (strlen(buffer_info.format) == 1) {
772	                    switch (buffer_info.format[0]) {
773	                        case 'e':
774	                            data_type = TYPE_FLOAT16;
775	                            table_data = buffer_info.buf;
776	                            break;
777	                        case 'f':
778	                            data_type = TYPE_FLOAT32;
779	                            table_data = buffer_info.buf;
780	                            break;
781	                        case 'd':
782	                            data_type = TYPE_DOUBLE;
783	                            table_data = buffer_info.buf;
784	                            break;
785	                    }
786	                }
787	            }
788	            PyBuffer_Release(&buffer_info);
789	        }
790	    }
791	
792	    if (!table_data) {
793	        free_table_data = 1;
794	        table_data = getlist(table, &table_size, wrong_size, TYPE_FLOAT32);
795	        if (!table_data) {
796	            return NULL;
797	        }
798	    }
799	
800	    /* malloc check ok, max is 2 * 4 * 65**3 = 2197000 */
801	    prepared = (INT16 *)malloc(sizeof(INT16) * table_size);
802	    if (!prepared) {
803	        if (free_table_data) {
804	            free(table_data);
805	        }
806	        return (INT16 *)ImagingError_MemoryError();
807	    }
808	
809	    for (i = 0; i < table_size; i++) {
810	        FLOAT16 htmp;
811	        double dtmp;
812	        switch (data_type) {
813	            case TYPE_FLOAT16:
814	                memcpy(&htmp, ((char *)table_data) + i * sizeof(htmp), sizeof(htmp));
815	                item = float16tofloat32(htmp);
816	                break;
817	            case TYPE_FLOAT32:
818	                memcpy(
819	                    &item, ((char *)table_data) + i * sizeof(FLOAT32), sizeof(FLOAT32));
820	                break;
821	            case TYPE_DOUBLE:
822	                memcpy(&dtmp, ((char *)table_data) + i * sizeof(dtmp), sizeof(dtmp));
823	                item = (FLOAT32)dtmp;
824	                break;
825	        }
826	        /* Max value for INT16 */
827	        if (item >= (0x7fff - 0.5) / (255 << PRECISION_BITS)) {
828	            prepared[i] = 0x7fff;
829	            continue;
830	        }
831	        /* Min value for INT16 */
832	        if (item <= (-0x8000 + 0.5) / (255 << PRECISION_BITS)) {
833	            prepared[i] = -0x8000;
834	            continue;
835	        }
836	        if (item < 0) {
837	            prepared[i] = item * (255 << PRECISION_BITS) - 0.5;
838	        } else {
839	            prepared[i] = item * (255 << PRECISION_BITS) + 0.5;
840	        }
841	    }
842	
843	#undef PRECISION_BITS
844	    if (free_table_data) {
845	        free(table_data);
846	    }
847	    return prepared;
848	}
