836	        if (item < 0) {
837	            prepared[i] = item * (255 << PRECISION_BITS) - 0.5;
838	        } else {
839	            prepared[i] = item * (255 << PRECISION_BITS) + 0.5;
840	        }
841	    }
842	
843	#undef PRECISION_BITS
844	    if (free_table_data) {
845	        free(table_data);
846	    }
847	    return prepared;
848	}
849	
850	static PyObject *
851	_color_lut_3d(ImagingObject *self, PyObject *args) {
852	    char *mode;
853	    int filter;
854	    int table_channels;
855	    int size1D, size2D, size3D;
856	    PyObject *table;
857	
858	    INT16 *prepared_table;
859	    Imaging imOut;
860	
861	    if (!PyArg_ParseTuple(
862	            args,
863	            "siiiiiO:color_lut_3d",
864	            &mode,
865	            &filter,
866	            &table_channels,
867	            &size1D,
868	            &size2D,
869	            &size3D,
870	            &table)) {
871	        return NULL;
872	    }
873	
874	    /* actually, it is trilinear */
875	    if (filter != IMAGING_TRANSFORM_BILINEAR) {
876	        PyErr_SetString(PyExc_ValueError, "Only LINEAR filter is supported.");
877	        return NULL;
878	    }
879	
880	    if (1 > table_channels || table_channels > 4) {
881	        PyErr_SetString(PyExc_ValueError, "table_channels should be from 1 to 4");
882	        return NULL;
883	    }
884	
885	    if (2 > size1D || size1D > 65 || 2 > size2D || size2D > 65 || 2 > size3D ||
886	        size3D > 65) {
887	        PyErr_SetString(
888	            PyExc_ValueError, "Table size in any dimension should be from 2 to 65");
889	        return NULL;
890	    }
891	
892	    prepared_table =
893	        _prepare_lut_table(table, table_channels * size1D * size2D * size3D);
894	    if (!prepared_table) {
895	        return NULL;
896	    }
897	
898	    imOut = ImagingNewDirty(mode, self->image->xsize, self->image->ysize);
899	    if (!imOut) {
900	        free(prepared_table);
901	        return NULL;
902	    }
903	
904	    if (!ImagingColorLUT3D_linear(
905	            imOut,
906	            self->image,
907	            table_channels,
908	            size1D,
909	            size2D,
910	            size3D,
911	            prepared_table)) {
912	        free(prepared_table);
913	        ImagingDelete(imOut);
914	        return NULL;
915	    }
916	
917	    free(prepared_table);
918	
919	    return PyImagingNew(imOut);

